/**
 * The slice of MAVLink 2 that a PX4 simulator speaks: PX4's simulator_mavlink
 * module sends HIL_ACTUATOR_CONTROLS (motor commands) and HEARTBEAT; the
 * simulator answers with HIL_SENSOR (IMU, magnetometer, barometer), HIL_GPS
 * and its own HEARTBEAT. Field order, sizes and CRC_EXTRA values are from
 * common.xml as generated by pymavlink (fields sorted by type size, extension
 * fields last). The unit tests check every frame byte for byte against
 * pymavlink's own encoder.
 */

export const MSG = {
  HEARTBEAT: 0,
  COMMAND_LONG: 76,
  HIL_ACTUATOR_CONTROLS: 93,
  HIL_SENSOR: 107,
  HIL_GPS: 113,
} as const;

const CRC_EXTRA: Record<number, number> = {
  [MSG.HEARTBEAT]: 50,
  [MSG.COMMAND_LONG]: 152,
  [MSG.HIL_ACTUATOR_CONTROLS]: 47,
  [MSG.HIL_SENSOR]: 108,
  [MSG.HIL_GPS]: 124,
};

/** Full (untruncated) payload length of each message we decode. */
const PAYLOAD_LEN: Record<number, number> = {
  [MSG.HEARTBEAT]: 9,
  [MSG.COMMAND_LONG]: 33,
  [MSG.HIL_ACTUATOR_CONTROLS]: 81,
  [MSG.HIL_SENSOR]: 65,
  [MSG.HIL_GPS]: 39,
};

const STX_V2 = 0xfd;
const STX_V1 = 0xfe;
const IFLAG_SIGNED = 0x01;

/** CRC-16/MCRF4XX (X.25), the MAVLink checksum. */
export function crcAccumulate(crc: number, byte: number): number {
  let tmp = (byte ^ (crc & 0xff)) & 0xff;
  tmp = (tmp ^ (tmp << 4)) & 0xff;
  return ((crc >> 8) ^ (tmp << 8) ^ (tmp << 3) ^ (tmp >> 4)) & 0xffff;
}

function crcOf(bytes: Uint8Array, start: number, end: number, extra: number): number {
  let crc = 0xffff;
  for (let i = start; i < end; i++) crc = crcAccumulate(crc, bytes[i] ?? 0);
  return crcAccumulate(crc, extra);
}

export interface Frame {
  msgid: number;
  sysid: number;
  compid: number;
  /** Payload zero-padded to the message's full length (MAVLink 2 trims trailing zeros). */
  payload: DataView;
}

export class MavlinkWriter {
  private seq = 0;
  constructor(
    readonly sysid = 1,
    readonly compid = 51,
  ) {}

  frame(msgid: number, payload: Uint8Array): Uint8Array {
    let len = payload.length;
    while (len > 1 && payload[len - 1] === 0) len--;
    const out = new Uint8Array(10 + len + 2);
    out[0] = STX_V2;
    out[1] = len;
    out[2] = 0;
    out[3] = 0;
    out[4] = this.seq;
    out[5] = this.sysid;
    out[6] = this.compid;
    out[7] = msgid & 0xff;
    out[8] = (msgid >> 8) & 0xff;
    out[9] = (msgid >> 16) & 0xff;
    out.set(payload.subarray(0, len), 10);
    const extra = CRC_EXTRA[msgid];
    if (extra === undefined) throw new RangeError(`no CRC_EXTRA for message ${msgid}`);
    const crc = crcOf(out, 1, 10 + len, extra);
    out[10 + len] = crc & 0xff;
    out[11 + len] = crc >> 8;
    this.seq = (this.seq + 1) & 0xff;
    return out;
  }

  heartbeat(h: { type: number; autopilot: number; baseMode: number; customMode: number; systemStatus: number }): Uint8Array {
    const b = new Uint8Array(9);
    const v = new DataView(b.buffer);
    v.setUint32(0, h.customMode >>> 0, true);
    b[4] = h.type;
    b[5] = h.autopilot;
    b[6] = h.baseMode;
    b[7] = h.systemStatus;
    b[8] = 3;
    return this.frame(MSG.HEARTBEAT, b);
  }

  hilSensor(s: HilSensor): Uint8Array {
    const b = new Uint8Array(65);
    const v = new DataView(b.buffer);
    v.setBigUint64(0, BigInt(Math.round(s.timeUsec)), true);
    const f = [s.xacc, s.yacc, s.zacc, s.xgyro, s.ygyro, s.zgyro, s.xmag, s.ymag, s.zmag];
    for (let i = 0; i < f.length; i++) v.setFloat32(8 + 4 * i, f[i] ?? 0, true);
    v.setFloat32(44, s.absPressure, true);
    v.setFloat32(48, s.diffPressure, true);
    v.setFloat32(52, s.pressureAlt, true);
    v.setFloat32(56, s.temperature, true);
    v.setUint32(60, s.fieldsUpdated >>> 0, true);
    b[64] = s.id;
    return this.frame(MSG.HIL_SENSOR, b);
  }

  hilGps(g: HilGps): Uint8Array {
    const b = new Uint8Array(39);
    const v = new DataView(b.buffer);
    v.setBigUint64(0, BigInt(Math.round(g.timeUsec)), true);
    v.setInt32(8, Math.round(g.latDeg * 1e7), true);
    v.setInt32(12, Math.round(g.lonDeg * 1e7), true);
    v.setInt32(16, Math.round(g.altM * 1000), true);
    v.setUint16(20, Math.round(g.ephCm), true);
    v.setUint16(22, Math.round(g.epvCm), true);
    v.setUint16(24, Math.round(Math.hypot(g.vn, g.ve) * 100), true);
    v.setInt16(26, Math.round(g.vn * 100), true);
    v.setInt16(28, Math.round(g.ve * 100), true);
    v.setInt16(30, Math.round(g.vd * 100), true);
    const cog = ((Math.atan2(g.ve, g.vn) * 180) / Math.PI + 360) % 360;
    v.setUint16(32, Math.hypot(g.vn, g.ve) > 0.2 ? Math.round(cog * 100) % 36000 : 65535, true);
    b[34] = g.fixType;
    b[35] = g.satellites;
    b[36] = g.id ?? 0;
    v.setUint16(37, 0, true);
    return this.frame(MSG.HIL_GPS, b);
  }
}

export interface HilSensor {
  timeUsec: number;
  /** Specific force, body FRD, m/s². */
  xacc: number;
  yacc: number;
  zacc: number;
  /** Body rates, FRD, rad/s. */
  xgyro: number;
  ygyro: number;
  zgyro: number;
  /** Magnetic field, body FRD, gauss. */
  xmag: number;
  ymag: number;
  zmag: number;
  /** hPa. */
  absPressure: number;
  diffPressure: number;
  pressureAlt: number;
  /** °C. */
  temperature: number;
  fieldsUpdated: number;
  id: number;
}

export interface HilGps {
  timeUsec: number;
  latDeg: number;
  lonDeg: number;
  /** AMSL, meters. */
  altM: number;
  ephCm: number;
  epvCm: number;
  /** NED velocity, m/s. */
  vn: number;
  ve: number;
  vd: number;
  fixType: number;
  satellites: number;
  id?: number;
}

/** HIL_SENSOR fields_updated bits (PX4 SensorSource). */
export const HIL_SENSOR_FIELDS = {
  ACCEL: 0b111,
  GYRO: 0b111000,
  MAG: 0b111000000,
  BARO: 0b1101000000000,
} as const;

export interface ActuatorControls {
  timeUsec: number;
  /** PX4 actuator outputs: motors are 0..1, other outputs -1..1. All zero while disarmed. */
  controls: Float32Array;
  mode: number;
  flags: number;
}

export function decodeActuatorControls(f: Frame): ActuatorControls {
  const v = f.payload;
  const controls = new Float32Array(16);
  for (let i = 0; i < 16; i++) controls[i] = v.getFloat32(16 + 4 * i, true);
  return {
    timeUsec: Number(v.getBigUint64(0, true)),
    flags: Number(v.getBigUint64(8, true)),
    controls,
    mode: v.getUint8(80),
  };
}

export interface Heartbeat {
  customMode: number;
  type: number;
  autopilot: number;
  baseMode: number;
  systemStatus: number;
}

export function decodeHeartbeat(f: Frame): Heartbeat {
  const v = f.payload;
  return {
    customMode: v.getUint32(0, true),
    type: v.getUint8(4),
    autopilot: v.getUint8(5),
    baseMode: v.getUint8(6),
    systemStatus: v.getUint8(7),
  };
}

/**
 * Streaming MAVLink 1/2 parser. Feed it bytes as they arrive (a TCP stream or
 * WebSocket chunks split anywhere); it returns every complete frame with a
 * good checksum for the messages it knows, and skips everything else.
 */
export class MavlinkParser {
  private buf = new Uint8Array(0);
  /** Frames dropped for a bad checksum. */
  badCrc = 0;

  push(chunk: Uint8Array): Frame[] {
    const merged = new Uint8Array(this.buf.length + chunk.length);
    merged.set(this.buf, 0);
    merged.set(chunk, this.buf.length);
    const out: Frame[] = [];
    let i = 0;
    while (i < merged.length) {
      const stx = merged[i];
      if (stx !== STX_V2 && stx !== STX_V1) {
        i++;
        continue;
      }
      const v2 = stx === STX_V2;
      const header = v2 ? 10 : 6;
      if (merged.length - i < header) break;
      const len = merged[i + 1] ?? 0;
      const signed = v2 && ((merged[i + 2] ?? 0) & IFLAG_SIGNED) !== 0;
      const total = header + len + 2 + (signed ? 13 : 0);
      if (merged.length - i < total) break;
      const msgid = v2
        ? (merged[i + 7] ?? 0) | ((merged[i + 8] ?? 0) << 8) | ((merged[i + 9] ?? 0) << 16)
        : (merged[i + 5] ?? 0);
      const extra = CRC_EXTRA[msgid];
      if (extra === undefined) {
        // Unknown message: trust the length and move on.
        i += total;
        continue;
      }
      const crc = crcOf(merged, i + 1, i + header + len, extra);
      const got = (merged[i + header + len] ?? 0) | ((merged[i + header + len + 1] ?? 0) << 8);
      if (crc !== got) {
        this.badCrc++;
        i++;
        continue;
      }
      const full = new Uint8Array(Math.max(len, PAYLOAD_LEN[msgid] ?? len));
      full.set(merged.subarray(i + header, i + header + len), 0);
      out.push({
        msgid,
        sysid: merged[i + (v2 ? 5 : 3)] ?? 0,
        compid: merged[i + (v2 ? 6 : 4)] ?? 0,
        payload: new DataView(full.buffer),
      });
      i += total;
    }
    this.buf = merged.slice(i);
    return out;
  }
}
